t=np.asarray(df['t']);A=np.asarray(df['A']);y=np.asarray(df['dA_dt'])
def lin(cols):
    X=np.column_stack(cols); c=np.linalg.lstsq(X,y,rcond=None)[0]; r=y-X@c
    return np.mean(r**2)/np.var(y), c
Tt=[1/t,np.ones_like(t),t,t**2]
best=(9,None)
